
import { ipcRenderer, webFrame } from 'electron';

type CoworkInvoke = (channel: string, ...args: any[]) => Promise<any>;
const coworkChevron = '<svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.4"><path d="m5 3 5 5-5 5"/></svg>';
const coworkSendIcon = '<svg width="17" height="17" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M10 16V4m-5 5 5-5 5 5"/></svg>';
const coworkRefreshIcon = '<svg width="15" height="15" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M16 7a6 6 0 1 0 0 6M16 3v4h-4"/></svg>';

function safeWebContent(html: string, fallback: string, owner = document): DocumentFragment {
  const parsed = new DOMParser().parseFromString(html || '', 'text/html');
  const allowed = new Set(['P','DIV','SPAN','BR','STRONG','B','EM','I','S','DEL','UL','OL','LI','H1','H2','H3','H4','H5','H6','BLOCKQUOTE','PRE','CODE','TABLE','THEAD','TBODY','TR','TH','TD','HR','A','SUP','SUB','KBD']);
  const blocked = new Set(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','FORM','INPUT','BUTTON','SVG','MATH','IMG','VIDEO','AUDIO']);
  const copy = (source: Node, target: Node) => {
    for (const child of Array.from(source.childNodes)) {
      if (child.nodeType === 3) { target.appendChild(owner.createTextNode(child.textContent || '')); continue; }
      if (child.nodeType !== 1) continue;
      const element = child as Element;
      if (blocked.has(element.tagName)) continue;
      if (!allowed.has(element.tagName)) { copy(child, target); continue; }
      const out = owner.createElement(element.tagName.toLowerCase());
      if (element.tagName === 'A') {
        try { const url = new URL(element.getAttribute('href') || ''); if (['https:','http:'].includes(url.protocol)) { out.setAttribute('href',url.href); out.setAttribute('target','_blank'); out.setAttribute('rel','noopener noreferrer'); } } catch {  }
      }
      copy(child, out); target.appendChild(out);
    }
  };
  const fragment = owner.createDocumentFragment(); copy(parsed.body, fragment);
  if (!fragment.textContent?.trim()) fragment.append(owner.createTextNode(fallback));
  return fragment;
}

