    this.reconcileChildren(thread,desired);thread.dataset.chatKey=chat;
    if(changed)thread.scrollTop=this.scrollPositions.get(chat)??thread.scrollHeight;
    else if(atEnd||this.sending)thread.scrollTop=thread.scrollHeight;
