    if((!prompt.trim()&&!(this.files.get(this.state?.chatId||'')||[]).length)||this.sending||this.navigating||!this.state?.ready||this.state?.busy)return;this.sending=true;this.error();this.paint();
    const startingChat=this.state?.chatId||'';
