      const holder=document.createElement('div');holder.className='agy-cowork-media';if(media.kind==='img'){holder.dataset.autoImage='true';holder.style.aspectRatio=(media.width&&media.height)?media.width+'/'+media.height:'1';}const button=document.createElement('button');button.type='button';button.textContent=media.kind==='img'?'Loading image…':media.label||(media.kind==='video'?'Play video':'Play audio');button.setAttribute('aria-label',media.label||(media.kind==='img'?'View image':'Play media'));holder.append(button);article.append(holder);
