  const previous = document.getElementById('agy-insights-popover');
  if (previous?.dataset.tab === initial && previous.dataset.anchor === (preferredAnchor?.id || 'agy-pill-context')) { closeInsightsPopover?.(); return; }
  closeInsightsPopover?.();
  const claude = document.body.classList.contains('agy-theme-claude');
  const anchor = preferredAnchor || document.getElementById(claude ? 'agy-pill-context' : 'agy-native-context');
  if (!anchor) return;
  const pop = insightNode('section'); pop.id = 'agy-insights-popover';
  pop.dataset.anchor = anchor.id; pop.dataset.tab = initial;
  if (claude) pop.className = 'agy-claude-popover';
  pop.setAttribute('role','dialog'); pop.setAttribute('aria-label','Context, usage and account limits');
  anchor.setAttribute('aria-expanded','true'); anchor.setAttribute('aria-controls',pop.id);
  const tabs = insightNode('div','','agy-context-tabs'); tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Context views');
  const pane = insightNode('div','','agy-compact-content'); pane.id='agy-compact-context-content';pane.setAttribute('role','tabpanel');
  pop.append(tabs,pane); document.body.append(pop);
