const poolAPI = {
  getStatus: async (): Promise<PoolStatusData> => {
    const status = await ipcRenderer.invoke('pool:get-status');
    syncClaudeIdentity(status);
    return status;
  },
  captureNative: (): Promise<{ success: boolean; account?: PoolAccountData; error?: string }> =>
    ipcRenderer.invoke('pool:capture-native'),
  startLogin: (): Promise<{ success: boolean; account?: PoolAccountData; error?: string }> =>
    ipcRenderer.invoke('pool:start-login'),
  cancelLogin: (): Promise<{ success: boolean }> => ipcRenderer.invoke('pool:cancel-login'),
  setActive: (id: string): Promise<{ success: boolean; error?: string }> => ipcRenderer.invoke('pool:set-active', id),
  setOptions: (opts: {
    geminiFallbackModel?: string;
    autoHotswap?: boolean;
    combineLimits?: boolean;
    quotaDisplayMode?: 'normalized' | 'additive' | 'active';
    showActiveInLimits?: boolean;
    soundEnabled?: boolean;
    soundTheme?: string;
    updateServerUrl?: string;
    autoCheckUpdates?: boolean;
    promptEngineMode?: 'antigravity' | 'claude' | 'custom';
    customPromptText?: string;
    uiThemeMode?: 'antigravity' | 'claude';
  }): Promise<{ success: boolean }> => ipcRenderer.invoke('pool:set-options', opts),
  checkAdmin: (): Promise<{ success: boolean; isAdmin: boolean; agentIsAdmin?: boolean | null; supported?: boolean }> => ipcRenderer.invoke('plus:check-admin'),
  relaunchAdmin: (): Promise<{ success: boolean; error?: string }> => ipcRenderer.invoke('plus:relaunch-admin'),
  removeAccount: (id: string): Promise<{ success: boolean }> => ipcRenderer.invoke('pool:remove-account', id),
  refreshQuota: (): Promise<{ success: boolean; summary?: unknown; error?: string }> =>
    ipcRenderer.invoke('pool:refresh-quota'),
  exportConfig: (): Promise<{ success: boolean; json?: string; error?: string }> =>
    ipcRenderer.invoke('pool:export-config'),
  importConfig: (jsonStr: string): Promise<{ success: boolean; count?: number; error?: string }> =>
    ipcRenderer.invoke('pool:import-config', jsonStr),
  getAudioData: (soundName: string): Promise<{ success: boolean; dataUri?: string; error?: string }> =>
    ipcRenderer.invoke('sound:get-audio-data', soundName),
  playSoundNative: (soundName: string): Promise<{ success: boolean; filePath?: string; error?: string }> =>
    ipcRenderer.invoke('sound:play-sound-native', soundName),
  openExternal: (url: string): Promise<{ success: boolean; error?: string }> =>
    ipcRenderer.invoke('shell:open-external', url),
  checkUpdate: (url?: string): Promise<{
    success: boolean;
    updateAvailable: boolean;
    currentVersion: string;
    latestVersion?: string;
    downloadUrl?: string;
    changelog?: string;
    releaseDate?: string;
    error?: string;
  }> => ipcRenderer.invoke('plus:check-update', url),
  downloadAndApplyUpdate: (downloadUrl: string): Promise<{ success: boolean; error?: string }> =>
    ipcRenderer.invoke('plus:download-and-apply-update', downloadUrl),
  onUpdateProgress: (callback: (p: { percent: number; downloadedBytes: number; totalBytes: number }) => void) => {
    const fn = (_e: any, d: any) => callback(d);
    ipcRenderer.on('plus:update-progress', fn);
    return () => ipcRenderer.removeListener('plus:update-progress', fn);
  },
};

