          const progressLabel = element('div', 'text-xs text-muted-foreground flex justify-between');
          const lblText = element('span', '', 'Downloading update…');
          const pctText = element('span', 'pct font-mono', '0%');
          progressLabel.append(lblText, pctText);
          const progressBar = element('div', 'w-full h-2 rounded-full bg-secondary overflow-hidden');
          const progressFill = element('div', 'h-full bg-green-500 rounded-full transition-all duration-150');
          progressFill.style.width = '0%';
          progressBar.append(progressFill);
          progressContainer.append(progressLabel, progressBar);

          const installBtn = createNativeButton(
            'Download & Install Update',
            async () => {
              (installBtn as HTMLButtonElement).disabled = true;
              installBtn.textContent = 'Downloading…';
              progressContainer.classList.remove('hidden');
              progressContainer.classList.add('flex');

              const unsubscribe = poolAPI.onUpdateProgress((p) => {
                progressFill.style.width = `${p.percent}%`;
                pctText.textContent = `${p.percent}%`;
              });

              try {
                const res = await poolAPI.downloadAndApplyUpdate(info.downloadUrl || '');
                unsubscribe();
                if (res.success) {
                  installBtn.textContent = 'Restarting…';
                  updateStatusEl.textContent = 'Patch applied! Relaunching Antigravity…';
                  updateStatusEl.className = 'text-xs text-green-400 font-medium';
                } else {
                  (installBtn as HTMLButtonElement).disabled = false;
                  installBtn.textContent = 'Retry Install';
                  updateStatusEl.textContent = res.error || 'Failed to install update';
                  updateStatusEl.className = 'text-xs text-red-400';
                }
              } catch (err: unknown) {
                unsubscribe();
                (installBtn as HTMLButtonElement).disabled = false;
                installBtn.textContent = 'Retry Install';
                const msg = err instanceof Error ? err.message : String(err);
                updateStatusEl.textContent = msg;
                updateStatusEl.className = 'text-xs text-red-400';
              }
            },
            true,
            ICONS.download,
          );

          banner.append(top, changelog, progressContainer, installBtn);
          updateBox.append(banner);
