  async function buildAccountPoolUI(container: HTMLElement, onUpdate?: () => void): Promise<void> {
    return buildNativeGeneralPlusUI(container, onUpdate);
  }

  function findSettingsGeneralTab(): HTMLElement | null {
    if (typeof document === 'undefined' || !document) return null;
    const dialog =
      document.querySelector('div[role="dialog"][aria-label="Settings"]') ||
      document.querySelector('.settings-modal-container') ||
      document.body;

    const navItems = Array.from(
      dialog.querySelectorAll<HTMLElement>('button[data-testid*="settings-nav-item"], button, [role="tab"]'),
    );

    for (const item of navItems) {
      if (item.id === 'agy-tab-general-plus') continue;
      const text = item.textContent?.trim();
      if (text === 'General') {
        return item;
      }
    }
    return null;
  }

  function findSettingsContentPane(): HTMLElement | null {
    if (typeof document === 'undefined' || !document) return null;
    const generalTab = findSettingsGeneralTab();
    if (generalTab) {

      let sidebar: HTMLElement | null = generalTab.parentElement;
      while (sidebar && sidebar.parentElement && sidebar.parentElement !== document.body) {
        const parent = sidebar.parentElement;
        const computed = window.getComputedStyle(parent);
        const isFlexRow = computed.display.includes('flex') && !computed.flexDirection.includes('column');
        if (isFlexRow && parent.children.length >= 2) {

          for (const child of Array.from(parent.children) as HTMLElement[]) {
            if (child.id === 'agy-general-plus-panel') continue;
            if (!child.contains(generalTab)) {
              return child;
            }
          }
        }
        sidebar = parent;
      }
    }

    const dialog =
      document.querySelector<HTMLElement>('div[role="dialog"][aria-label="Settings"]') ||
      document.querySelector<HTMLElement>('.settings-modal-container');
    if (dialog) {
      const grow = dialog.querySelector<HTMLElement>('.grow.w-full');
      if (grow) return grow;

      const wideCols = Array.from(dialog.querySelectorAll<HTMLElement>('div')).filter((d) => {
        const r = d.getBoundingClientRect();
        return r.width >= 400 && r.height >= 300;
      });
      if (wideCols.length > 0) {
        return wideCols[wideCols.length - 1];
      }
    }

    return null;
  }

  let nativeSettingsDelegationAttached = false;
  function injectGeneralPlusTab(): void {
    if (!nativeSettingsDelegationAttached) {
      nativeSettingsDelegationAttached = true;
      document.addEventListener("click", event => {
        const target = event.target instanceof Element ? event.target.closest<HTMLElement>('[data-testid^="settings-nav-item-"]') : null;
        if (target && target.id !== "agy-tab-general-plus") deactivateGeneralPlusTab();
      }, true);
    }
    if (typeof document === 'undefined' || !document || !document.body) return;
    if (document.getElementById('agy-tab-general-plus')) return;

    const generalTab = findSettingsGeneralTab();
    if (!generalTab || !generalTab.parentElement) return;

    const plusTab = generalTab.cloneNode(true) as HTMLElement;
    plusTab.id = 'agy-tab-general-plus';
    plusTab.setAttribute('data-agy-tab', 'general-plus');
    plusTab.setAttribute('data-testid', 'settings-nav-item-GeneralPlus');

    plusTab.className =
      'flex items-center gap-1.5 group mx-2 px-2 py-1 rounded-lg cursor-pointer border-none text-left transition-all outline-none hover:bg-sidebar-muted';
    const span = plusTab.querySelector('span');
    if (span) {
      span.textContent = 'General+';
      span.className =
        'text-sm transition-colors select-none truncate flex-1 text-secondary-foreground group-hover:text-foreground';
    } else {
      plusTab.textContent = 'General+';
    }

    if (generalTab.nextSibling) {
      generalTab.parentElement.insertBefore(plusTab, generalTab.nextSibling);
    } else {
      generalTab.parentElement.appendChild(plusTab);
    }

    plusTab.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      activateGeneralPlusTab(plusTab, generalTab);
    });

    Array.from(generalTab.parentElement.children).forEach((child) => {
      if (child !== plusTab) {
        child.addEventListener('click', () => {
          deactivateGeneralPlusTab(plusTab);
        });
      }
    });
  }

  function activateGeneralPlusTab(plusTab: HTMLElement, _generalTab?: HTMLElement): void {
    plusTab.className =
      'flex items-center gap-1.5 group mx-2 px-2 py-1 rounded-lg cursor-pointer border-none text-left transition-all outline-none bg-sidebar-secondary agy-active-tab';
    plusTab.style.backgroundColor = 'rgba(255, 255, 255, 0.08)';
    plusTab.style.borderRadius = '8px';
    const plusSpan = plusTab.querySelector('span');
    if (plusSpan) {
      plusSpan.className = 'text-sm transition-colors select-none truncate flex-1 text-foreground';
    }

    const contentPane = findSettingsContentPane();
    if (!contentPane || !contentPane.parentElement) return;


    contentPane.style.display = 'none';
    contentPane.setAttribute('data-agy-pane-hidden', 'true');

    let panel = document.getElementById('agy-general-plus-panel');
    if (!panel) {
      panel = document.createElement('div');
      panel.id = 'agy-general-plus-panel';
      contentPane.parentElement.insertBefore(panel, contentPane.nextSibling);
    }
    panel.className = 'flex-1 grow overflow-y-auto h-full box-border';
    panel.style.display = 'block';
    panel.style.flex = '1 1 0%';
    panel.style.width = '100%';
    panel.style.height = '100%';
    panel.style.overflowY = 'auto';
    panel.style.backgroundColor = '#121316';
    panel.style.color = 'var(--foreground, #f3f4f6)';
    panel.style.position = 'relative';
    panel.style.zIndex = '30';

    void buildNativeGeneralPlusUI(panel);
  }

  function deactivateGeneralPlusTab(plusTab?: HTMLElement): void {
    const tab = plusTab || document.getElementById('agy-tab-general-plus');
    if (tab) {
      tab.className =
        'flex items-center gap-1.5 group mx-2 px-2 py-1 rounded-lg cursor-pointer border-none text-left transition-all outline-none hover:bg-sidebar-muted';
      tab.style.backgroundColor = 'transparent';
      tab.classList.remove('agy-active-tab');
      tab.classList.remove('bg-sidebar-secondary');
      const span = tab.querySelector('span');
      if (span) {
        span.className =
          'text-sm transition-colors select-none truncate flex-1 text-secondary-foreground group-hover:text-foreground';
      }
    }

    const panel = document.getElementById('agy-general-plus-panel');
    if (panel) {
      panel.style.display = 'none';
    }


    const hiddenPanes = document.querySelectorAll<HTMLElement>('[data-agy-pane-hidden="true"]');
    hiddenPanes.forEach((p) => {
      p.style.display = '';
      p.removeAttribute('data-agy-pane-hidden');
    });
  }


  function updatePoolPill(): void {
    if (typeof document === 'undefined' || !document) return;
    const pill = document.getElementById('agy-pool-pill');
    if (!pill) return;
    poolAPI
      .getStatus()
      .then((data) => {
        if (!data.success) return;
        const count = data.accounts?.length || 0;
        const textNode = pill.querySelector('.agy-pill-text');
        const badgeNode = pill.querySelector('.agy-pill-badge');
        if (textNode) {
          textNode.textContent = count === 0 ? 'No Accounts' : `${count} Acc${count > 1 ? 's' : ''}`;
        }
        if (badgeNode) {
          const total = data.summary?.totalCapacityPercent ?? count * 100;
          badgeNode.textContent = count === 0 ? '0%' : `${total}%`;
          badgeNode.setAttribute('data-state', total > 30 ? 'ok' : 'warn');
        }
      })
      .catch(() => {});
  }

